// Parse and log the incoming notification
const input = $input.first().json;

const notification = {
  operation_id: input.operation_id,
  request_id: input.request_id,
  status: input.status,
  operation_type: input.operation_type,
  target_service: input.target_service,
  received_at: new Date().toISOString(),
  notification_id: crypto.randomUUID()
};

// Process based on status
if (input.status === "SUCCESS") {
  notification.type = "success";
  notification.result = input.result || {};
  notification.user_data = input.user_data || {};
  notification.message = `Provisioning completed successfully for ${input.user_data?.username || 'unknown'} on ${input.target_service}`;
} else if (input.status === "FAILED") {
  notification.type = "failure";
  notification.error = input.error || {};
  notification.message = `Provisioning failed for operation ${input.operation_id}: ${input.error?.message || 'Unknown error'}`;
  notification.retry_count = input.error?.retry_count || 0;
} else if (input.status === "DLQ") {
  notification.type = "dlq";
  notification.error = input.error || {};
  notification.message = `ALERT: Operation ${input.operation_id} sent to Dead Letter Queue after ${input.error?.retry_count || 'unknown'} retries`;
  notification.escalation_required = true;
} else {
  notification.type = "unknown";
  notification.message = `Unknown notification status: ${input.status}`;
}

// Log entry for audit trail
notification.log_entry = {
  timestamp: notification.received_at,
  level: notification.type === "success" ? "INFO" : (notification.type === "dlq" ? "ERROR" : "WARN"),
  source: "gateway-iam",
  operation_id: notification.operation_id,
  message: notification.message
};

return [{ json: notification }];

// Format success notification response
const input = $input.first().json;

return [{
  json: {
    status: "sent",
    notification_id: input.notification_id,
    sent_at: new Date().toISOString(),
    notification_type: "success",
    details: {
      operation_id: input.operation_id,
      message: input.message,
      target_service: input.target_service,
      service_user_id: input.result?.service_user_id,
      username: input.user_data?.username
    }
    // In production: could trigger email/Slack notification here
    // Email subject: "Provisioning Success - ${input.user_data.username}"
  }
}];

// Format failure notification response
const input = $input.first().json;

return [{
  json: {
    status: "sent",
    notification_id: input.notification_id,
    sent_at: new Date().toISOString(),
    notification_type: "failure",
    details: {
      operation_id: input.operation_id,
      message: input.message,
      error: input.error?.message,
      retry_count: input.retry_count,
      target_service: input.target_service
    }
    // In production: could trigger alert notification
    // Email subject: "Provisioning Failed - Operation ${input.operation_id}"
  }
}];

// Format DLQ escalation alert
const input = $input.first().json;

return [{
  json: {
    status: "sent",
    notification_id: input.notification_id,
    sent_at: new Date().toISOString(),
    notification_type: "dlq_alert",
    escalation: {
      required: true,
      priority: "HIGH",
      assigned_to: "iam-admin-team"
    },
    details: {
      operation_id: input.operation_id,
      message: input.message,
      error: input.error?.message,
      retry_count: input.error?.retry_count,
      target_service: input.target_service,
      action_required: "Manual intervention needed. Check DLQ via API endpoint: GET /api/v1/provisioning?status=DLQ"
    }
    // In production: MUST trigger immediate alert
    // Slack: @channel CRITICAL - DLQ Alert
    // Email (high priority): "URGENT: Operation Sent to Dead Letter Queue"
  }
}];
